    const f=await start();await act(f,'quicklinks:new');expect(top(f).view).toMatchObject({kind:'form',title:'New quicklink',fields:[{title:'Name',value:''},{title:'URL',value:''},{},{},{}]});expect(f.api.saveQuicklink).not.toHaveBeenCalled();await save(f,'  Public Saved  ','HTTPS://EXAMPLE.ORG:443/public');expect(f.api.saveQuicklink).toHaveBeenCalledExactlyOnceWith({expectedRevision:0,name:'Public Saved',url:'https://example.org/public'});expect(items(f)).toHaveLength(3);expect(top(f).selection).toBe(id(501));expect(f.api.listQuicklinks).toHaveBeenCalledTimes(2);expect(f.api.openQuicklink).not.toHaveBeenCalled();expect(f.dismiss).not.toHaveBeenCalled();
